/* Read an authorized short-lived job URL locally; never publish or retain its bytes. */
(function(root){'use strict';root.MIRPrivateDocumentViewer={async open({url,name='Document chantier'}){
 const c=root.MIRPortalConfig,u=new URL(url);if(c?.environment!=='test'||c?.projectRef!=='hxtztkmbfpmzrieccwsg'||u.protocol!=='https:'||u.hostname!=='hxtztkmbfpmzrieccwsg.supabase.co'||!u.pathname.startsWith('/storage/v1/object/sign/mir-job-documents/')||!u.searchParams.get('token'))throw Error('Lien de document privé non autorisé.');
 const box=document.createElement('dialog');box.id='mir-private-document';box.className='portal-dialog';box.innerHTML='<header><h2></h2><button type="button" data-close>Fermer</button></header><nav aria-label="Lecture du document"><button type="button" data-prev aria-label="Page précédente">←</button><span data-page role="status"></span><button type="button" data-next aria-label="Page suivante">→</button><button type="button" data-less aria-label="Réduire">−</button><button type="button" data-more aria-label="Agrandir">＋</button><a data-download>Télécharger</a></nav><p data-message role="status">Chargement du document privé…</p><div class="mir-private-document-frame"><canvas></canvas><img alt="Document chantier" hidden></div>';
 box.querySelector('h2').textContent=name;document.body.append(box);const $=s=>box.querySelector(s);let doc=null,loading=null,task=null,blobURL=null,pageNumber=1,zoom=1,closed=false;
 $('[data-close]').onclick=()=>box.close();box.addEventListener('close',()=>{closed=true;task?.cancel();if(loading)void loading.destroy().catch(()=>{});if(blobURL)URL.revokeObjectURL(blobURL);box.remove();},{once:true});box.showModal();
 async function draw(){if(!doc||closed)return;try{task?.cancel();const p=await doc.getPage(pageNumber);if(closed)return;const canvas=$('canvas'),frame=$('.mir-private-document-frame'),size=p.getViewport({scale:1}),ratio=Math.min(2,devicePixelRatio||1),v=p.getViewport({scale:(frame.clientWidth||700)/size.width*zoom*ratio});canvas.width=Math.ceil(v.width);canvas.height=Math.ceil(v.height);canvas.style.width=v.width/ratio+'px';canvas.style.height=v.height/ratio+'px';$('[data-page]').textContent=pageNumber+' / '+doc.numPages+' · '+Math.round(zoom*100)+' %';task=p.render({canvasContext:canvas.getContext('2d'),viewport:v});await task.promise;}catch(e){if(e.name!=='RenderingCancelledException')$('[data-message]').textContent='Lecture indisponible : '+e.message;}}
 $('[data-prev]').onclick=()=>{if(pageNumber>1){pageNumber--;void draw();}};$('[data-next]').onclick=()=>{if(doc&&pageNumber<doc.numPages){pageNumber++;void draw();}};$('[data-less]').onclick=()=>{zoom=Math.max(.5,zoom/1.25);void draw();};$('[data-more]').onclick=()=>{zoom=Math.min(4,zoom*1.25);void draw();};
 try{const response=await fetch(u.href,{credentials:'omit'});if(!response.ok)throw Error('Le document privé ne peut pas être ouvert.');const blob=await response.blob();if(!blob.size||blob.size>20*1024*1024)throw Error('Taille du document invalide.');if(closed)return;blobURL=URL.createObjectURL(blob);$('[data-download]').href=blobURL;$('[data-download]').download=name.replace(/[^\p{L}\p{N} ._-]/gu,'')+(blob.type==='application/pdf'?'.pdf':'');
 if(blob.type==='application/pdf'){const P=await import('./vendor/pdfjs/pdf.min.mjs');P.GlobalWorkerOptions.workerSrc=new URL('vendor/pdfjs/pdf.worker.min.mjs',document.baseURI).href;loading=P.getDocument({data:await blob.arrayBuffer()});doc=await loading.promise;if(closed){await loading.destroy();return;}await draw();}else if(/^image\/(png|jpeg|webp)$/.test(blob.type)){$('canvas').hidden=true;$('img').hidden=false;$('img').src=blobURL;}else throw Error('Format de document non pris en charge.');$('[data-message]').textContent='Document privé du chantier · accès vérifié.';
 }catch(e){if(!closed)$('[data-message]').textContent=e.message;}
 }};})(window);
